var mlContext = new MLContext(seed: 0);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
Console.WriteLine($"Loading data from: {dataPath}");
Console.WriteLine($"File exists: {File.Exists(dataPath)}");

var dataView = mlContext.Data.LoadFromTextFile<TicketData>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

Console.WriteLine("Data loaded");

var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
    .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

Console.WriteLine("Fitting...");
var model = pipeline.Fit(dataView);
Console.WriteLine("Fitted!");

var predictions = model.Transform(dataView);
var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");
Console.WriteLine($"MacroAccuracy: {metrics.MacroAccuracy}");
Console.WriteLine($"MicroAccuracy: {metrics.MicroAccuracy}");

// Try to get labels
var schema = predictions.Schema;
var keyCol = schema["Label"];
Console.WriteLine($"Label column type: {keyCol.Type}");

var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
try {
    keyCol.GetSlotNames(ref labelBuffer);
    Console.WriteLine($"SlotNames length: {labelBuffer.Length}");
} catch (Exception ex) {
    Console.WriteLine($"GetSlotNames failed: {ex.Message}");
}

try {
    keyCol.Annotations.GetValue("KeyValues", ref labelBuffer);
    Console.WriteLine($"KeyValues length: {labelBuffer.Length}");
    foreach (var v in labelBuffer.DenseValues())
        Console.WriteLine($"  Label: {v}");
} catch (Exception ex) {
    Console.WriteLine($"KeyValues failed: {ex.Message}");
}

Console.WriteLine("Done!");
